#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y, vector<pair<int,int>>& ops) {
    int n = p.size();
    assert(x > 0 && y > 0 && x + y < n);
    ops.push_back({x, y});
    vector<int> np;
    // suffix: p[n-y .. n-1]
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    // middle: p[x .. n-y-1]
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    // prefix: p[0 .. x-1]
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n - 2; placed++) {
        int pos = -1;
        for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        // Step 1: Move element from pos to position n-1 (last)
        if (pos < n - 1) {
            // x = pos+1, y = n-1-pos: swaps prefix[0..pos] with suffix[pos+1..n-1]
            // But x+y = pos+1 + n-1-pos = n, need x+y < n, so middle must be non-empty
            // Use x = pos+1, y = n-1-pos-1 = n-pos-2 if possible (need y>0 => pos < n-2)
            // That leaves middle of size 1. Element at pos goes to end of new array (position n-1-(n-pos-2)... no)
            // Actually with x=pos+1, y=n-pos-2: element at p[pos] is last of prefix, goes to position n-1 after swap? No, prefix goes to END.
            // New array: suffix(y) | middle(1) | prefix(x). Element at pos (last of prefix) goes to position n-1. Yes!
            if (pos < n - 2) {
                apply_op(p, pos + 1, n - pos - 2, ops);
                // Verify element is now at n-1
                // Actually prefix [0..pos] goes to positions [n-pos-1 .. n-1], so p[pos] -> position n-1. Correct!
            } else {
                // pos == n-2: element is at second-to-last. Use x=1, y=1 to rotate if n>3
                // Or x=n-2, y=1: prefix=[0..n-3], suffix=[n-1]. New: [p[n-1], p[n-2], p[0..n-3]]
                // p[n-2] goes to position n-1. 
                apply_op(p, n - 2, 1, ops);
            }
            pos = n - 1;
        }

        // Step 2: Move element from position n-1 to position placed
        // x = placed+1, y = 1: suffix=[p[n-1]], middle=[p[placed+1..n-2]], prefix=[p[0..placed]]
        // New: [p[n-1], p[placed+1..n-2], p[0..placed]]. Element goes to position 0, not placed.
        // Use x = placed, y = 1 if placed > 0:
        // New: [p[n-1], p[placed..n-2], p[0..placed-1]]. Element at position 0.
        // Hmm. Let me use: x=1, y=n-1-placed. suffix = [p[placed+1..n-1]], but element is at n-1 which is in suffix at last position. After op: [suffix, middle, prefix]. Element at position n-1-placed-1... complex.
        // Simplest: x = placed+1, y = 1. Element (at n-1, which is suffix) goes to position 0. Then it's wrong unless placed==0.
        if (placed == 0) {
            apply_op(p, 1, 1, ops);
        } else {
            // Two-step not needed if we think differently.
            // x=placed, y=1: new=[p[n-1]] + p[placed..n-2] + p[0..placed-1]. Element at pos 0. Need it at pos placed.
            // Instead: use the fact that we can choose any x,y. We want p[n-1] at position placed.
            // After op(x,y): suffix[y] goes to front, prefix[x] goes to end. p[n-1] is last of suffix when y>=1.
            // p[n-1] goes to position y-1 in new array. We want y-1 = placed => y = placed+1.
            // Need x + y < n => x < n - placed - 1. And x > 0. So x=1 works if 1+placed+1 < n => placed < n-2 (true since placed < n-2).
            apply_op(p, 1, placed + 1, ops);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
